    if not isinstance(n, int) or n < 1:
        raise ValueError("n must be a positive integer")
    sum = 0
    for i in range(1, int(n ** 0.5) + 1):
        if n % i == 0 and i % 2 == 0:
            sum += i
            if i != n // i and n // i % 2 == 0:
                sum += n // i
    return sum

