def unique_product(nums):
    """
    This function calculates the product of all unique numbers in a given list.

    Args:
        nums (list): A list of integers.

    Returns:
        int: The product of all unique numbers in the list.
    """
    # Create a set of unique numbers from the input list
    unique_nums = set(nums)

    # Initialize the product to 1
    product = 1

    # Loop through each unique number and multiply the product by the number
    for num in unique_nums:
        product *= num

    # Return the product of the unique numbers
    return product

