def max_product_tuple(tuples):
    """
    Find the maximum absolute product of two numbers in a list of tuples.

    Args:
        tuples (list): A list of tuples, where each tuple contains two numbers.

    Returns:
        float: The maximum absolute product of two numbers in the list. If the input list is empty, returns None.

    Raises:
        ValueError: If a tuple contains non-numeric values or if the input list is empty.
    """
    if not tuples:
        return None
    max_product = math.inf
    for tup in tuples:
        if len(tup) != 2:
            raise ValueError("Each tuple must contain exactly two numbers")
        for val in tup:
            if not isinstance(val, (int, float)):
                raise ValueError(f"Tuple {tup} contains non-numeric value {val}")
        product = abs(tup[0] * tup[1])
        max_product = max(max_product, product)
    return max_product
