    """
    Calculate the sum of the smallest and largest numbers in a list.

    Args:
        lst (list): A list of numbers.

    Returns:
        int or None: The sum of the smallest and largest numbers in the list, or None if the list is empty.
    """
    if not lst:
        return None
    return min(lst) + max(lst)

def big_sum_of_lists(lists):
    """
    Calculate the sum of the smallest and largest numbers in each list of a given list of lists.

    Args:
        lists (list): A list of lists, where each inner list contains numbers.

    Returns:
        list: A new list where each element is the sum of the smallest and largest numbers in the corresponding list from the input.
    """
    return [big_sum(lst) for lst in lists]
